public function test_batch_endpoint_recalculates_remaining_sessions_using_completed_status(): void
{
    // ... total_classes = 8, confirmed_dates = 3, future_dates = 5
    $this->assertDatabaseHas('StudentClass', [
        'ID' => $studentClassId,
        'SessionCount' => 8,
        'UsedSessions' => 3,
